            return matrix

def is_valid_matrix(matrix):
    N = len(matrix)

    # Check if all elements are distinct and within the range [0, 1000]
    elements = [matrix[i][j] for i in range(N) for j in range(N) if i != j]
    if len(set(elements)) != len(elements) or any(e < 0 or e > 1000 for e in elements):
        return False

    # Check if the matrix is symmetric
    for i in range(N):
        for j in range(N):
            if matrix[i][j] != matrix[j][i]:
                return False

    # Check if the diagonal elements are zero
    for i in range(N):
        if matrix[i][i] != 0:
            return False

